list_categories.code:
import (
	"fmt"
)

resp, err := client.Categories().ListCategories(ctx, map[string]any{"limit": 10, "offset": 10, "sort": "name", "dir": "asc"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["categories"].([]any) {
	category := row.(map[string]any)
	fmt.Println(category["id"], category["general"].(map[string]any)["name"])
}
fmt.Println(body["pagination"].(map[string]any)["has_next"])

