create_category.code:
import (
	"fmt"
)

resp, err := client.Categories().CreateCategory(ctx, map[string]any{
	"category": map[string]any{
		"general": map[string]any{
			"name":            "Seasonal Produce",
			"title":           "Seasonal Produce",
			"heading":         "Fresh this season",
			"summary":         "Fruit and vegetables picked this week",
			"parent_category": map[string]any{"id": 4310},
		},
		"description":             map[string]any{"content": "<p>What is in season right now.</p>"},
		"availability_visibility": map[string]any{"visible": true, "custom_sorting": true, "default_sorting": "alpha_asc"},
		"tax_shipping":            map[string]any{"tax_message": "Prices include GST"},
		"assign_products":         map[string]any{"products": []any{101, 102}},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
category := resp.Map().(map[string]any)["category"].(map[string]any)
general := category["general"].(map[string]any)
fmt.Println(category["id"], general["sku"], general["url"])

